  function cropFromPoints(a,b){const sx=Math.max(0,Math.min(width-1,Math.floor(a.x))),sy=Math.max(0,Math.min(height-1,Math.floor(a.y))),dx=b.x>=sx?1:-1,dy=b.y>=sy?1:-1,availableW=dx>0?width-sx:sx,availableH=dy>0?height-sy:sy,r=Number($('cropRatio').value);let w=Math.max(1,Math.round(Math.abs(b.x-sx))),h=Math.max(1,Math.round(Math.abs(b.y-sy)));if(r){if(w/h>r)h=Math.max(1,Math.round(w/r));else w=Math.max(1,Math.round(h*r));const scale=Math.min(1,availableW/w,availableH/h);w=Math.max(1,Math.round(w*scale));h=Math.max(1,Math.round(h*scale));}w=Math.min(w,availableW||1);h=Math.min(h,availableH||1);return{x:dx>0?sx:Math.max(0,sx-w),y:dy>0?sy:Math.max(0,sy-h),w,h};}
