  function beginTransform(p,e){if(!editable())return;const t=prepareTransform();if(!t){tell('Слой пуст: перемещать нечего.');return;}const b=t.box,r=9/zoom,corners=[[b.x,b.y,'nw'],[b.x+b.w,b.y,'ne'],[b.x,b.y+b.h,'sw'],[b.x+b.w,b.y+b.h,'se']],hit=corners.find(([x,y])=>Math.hypot(x-p.x,y-p.y)<=r);gesture={...t,kind:'transform',before:snapshot(),original:{...b},box:{...b},start:p,handle:hit?.[2],angle:0,pointerId:e.pointerId};}
